-// Kernel CUDA naïf : Simulation gravitationnelle N-Corps (N-Body)
+struct SourceParticle {
+    float x, y, z, mass;
+};
+
+static constexpr int SOURCE_TILE_SIZE = 256;
+
+__device__ __forceinline__ void accumulate_source_force(
+    const Particle& target,
+    const SourceParticle& source,
+    float G,
+    float softening,
+    float& fx,
+    float& fy,
+    float& fz) {
+    const float dx = source.x - target.x;
+    const float dy = source.y - target.y;
+    const float dz = source.z - target.z;
+
+    const float distSq = dx * dx + dy * dy + dz * dz + softening;
+    const float invDist = rsqrtf(distSq);
+    float invDistCube;
+    if (invDist == 0.0f) {
+        invDistCube = 0.0f;
+    } else {
+        const float invDistSq = invDist * invDist;
+        const float squareError = fmaf(distSq, invDistSq, -1.0f);
+        const float cubeCorrection = fmaf(-1.5f, squareError, 1.0f);
+        invDistCube = (invDistSq * invDist) * cubeCorrection;
+    }
+
+    const float f = (G * target.mass * source.mass) * invDistCube;
+    fx += f * dx;
+    fy += f * dy;
+    fz += f * dz;
+}
+
+// Each CTA stages source particles in shared-memory chunks. Each active
+// thread still owns exactly one target and accumulates its output locally.
 extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
-    int i = blockIdx.x * blockDim.x + threadIdx.x;
-    if (i >= n) return;
+    extern __shared__ SourceParticle source_tile[];
+
+    const int i = blockIdx.x * blockDim.x + threadIdx.x;
+    const bool active = i < n;
+    Particle target;
+    if (active) {
+        target = in[i];
+    }

     const float G = 1.0f;
     const float softening = 0.001f;
@@ -18,27 +61,43 @@ extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, i
     float fy = 0.0f;
     float fz = 0.0f;

-    // Approche naïve : chaque thread parcourt toutes les particules en mémoire globale
-    // sans utiliser de mémoire partagée (__shared__) ni mettre in[i] en registre.
-    for (int j = 0; j < n; j++) {
-        if (i == j) continue; // Divergence de branche inutile dans la boucle
-
-        float dx = in[j].x - in[i].x;
-        float dy = in[j].y - in[i].y;
-        float dz = in[j].z - in[i].z;
+    for (int tile_begin = 0; tile_begin < n;) {
+        int tile_size = n - tile_begin;
+        if (tile_size > SOURCE_TILE_SIZE) {
+            tile_size = SOURCE_TILE_SIZE;
+        }

-        float distSq = dx * dx + dy * dy + dz * dz + softening;
-        float dist = sqrtf(distSq); // Calcul coûteux (au lieu de rsqrtf)
+        for (int k = threadIdx.x; k < tile_size; k += blockDim.x) {
+            const int source_index = tile_begin + k;
+            source_tile[k].x = in[source_index].x;
+            source_tile[k].y = in[source_index].y;
+            source_tile[k].z = in[source_index].z;
+            source_tile[k].mass = in[source_index].mass;
+        }
+        __syncthreads();

-        float f = (G * in[i].mass * in[j].mass) / (distSq * dist);
-
-        fx += f * dx;
-        fy += f * dy;
-        fz += f * dz;
+        if (active) {
+            const int self_k = i - tile_begin;
+            if (self_k >= 0 && self_k < tile_size) {
+                for (int k = 0; k < self_k; ++k) {
+                    accumulate_source_force(target, source_tile[k], G, softening, fx, fy, fz);
+                }
+                for (int k = self_k + 1; k < tile_size; ++k) {
+                    accumulate_source_force(target, source_tile[k], G, softening, fx, fy, fz);
+                }
+            } else {
+                for (int k = 0; k < tile_size; ++k) {
+                    accumulate_source_force(target, source_tile[k], G, softening, fx, fy, fz);
+                }
+            }
+        }
+        __syncthreads();
+        tile_begin += tile_size;
     }

-    // Intégration d'Euler explicite
-    Particle p = in[i];
+    if (!active) return;
+
+    Particle p = target;
     p.vx += (fx / p.mass) * dt;
     p.vy += (fy / p.mass) * dt;
     p.vz += (fz / p.mass) * dt;
@@ -49,4 +108,3 @@ extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, i

     out[i] = p;
 }
